urlset:
{%- for sitemap_entry in entries %}
{%- if not sitemap_entry.extra.noindex %}
{%- set url_path = sitemap_entry.permalink | replace(from=config.base_url, to="") %}
{%- set lastmod = lastmods | get(key=url_path, default=sitemap_entry.updated | default(value="")) %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if lastmod %}
    {{ lastmod }}
    {%- endif %}

{%- endif %}
{%- endfor %}
